<?php $title="Sales";require "includes/header.php";$r=$conn->query("SELECT s.*,c.name customer,b.name bicycle FROM sales s JOIN customers c ON c.id=s.customer_id JOIN bicycles b ON b.id=s.bicycle_id ORDER BY s.id DESC");?><div class="section-title"><div><h2>🛒 Sales & Orders</h2><p class="muted">Revenue and bicycle order tracking.</p></div><a class="btn primary" href="add_sale.php">+ New Sale</a></div><div class="card"><table><tr><th>Invoice</th><th>Customer</th><th>Bicycle</th><th>Amount</th><th>Payment</th><th>Date</th></tr><?php while($x=$r->fetch_assoc()):?><tr><td>#<?=e($x["invoice_no"])?></td><td><?=e($x["customer"])?></td><td><?=e($x["bicycle"])?></td><td><?=money($x["amount"])?></td><td><span class="badge"><?=e($x["payment"])?></span></td><td><?=e($x["sale_date"])?></td></tr><?php endwhile;?></table></div><?php require "includes/footer.php";?>